UPDATE email_threads t SET is_signal = calc.signal FROM (SELECT EXISTS ( SELECT 1 FROM email_messages m JOIN email_message_mailbox_facts facts ON facts.id = m.id LEFT JOIN email_contacts c ON c.id = m.from_contact_id CROSS JOIN LATERAL ( SELECT COALESCE(bool_or(f.is_important) FILTER (WHERE lower(f.email_address) = lower(c.email_address)),false) AS address_true, COALESCE(bool_or(NOT f.is_important) FILTER (WHERE lower(f.email_address) = lower(c.email_address)),false) AS address_false, COALESCE(bool_or(f.is_important) FILTER (WHERE lower(f.email_domain) = lower(split_part(c.email_address,'@',2))),false) AS domain_true, COALESCE(bool_or(NOT f.is_important) FILTER (WHERE lower(f.email_domain) = lower(split_part(c.email_address,'@',2))),false) AS domain_false FROM email_filters f WHERE f.link_id = m.link_id ) rules WHERE m.thread_id = $1 AND facts.is_present AND NOT facts.in_trash AND lower(split_part(c.email_address,'@',2)) IS DISTINCT FROM $2 AND (rules.address_true OR (rules.domain_true AND NOT rules.address_false) OR (NOT (rules.address_false OR (rules.domain_false AND NOT rules.address_true)) AND facts.provider_is_primary)) ) AS signal) calc WHERE t.id = $1 AND t.is_signal IS DISTINCT FROM calc.signal
